-- Source SHA256: C0355F6D45C0A72117C2FEA15AEBB73BE29D8D294EF1976D901DD03FB595116D
-- Local replay required before any staging promotion.
create or replace function finance_private.integration_error_is_in_scope(p_error_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$select false$$;
create or replace function finance_api.list_integration_errors(p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_status text,p_source_system text,p_cursor text,p_limit integer) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,finance,finance_private as $$
declare v_limit integer:=coalesce(p_limit,50);v_cursor_time timestamptz;v_cursor_id uuid;v_items jsonb;v_has_more boolean;v_next_cursor text;
begin
 if not finance_api.authorize_scope(p_legal_entity_id,p_dealer_account_id,p_branch_id,'listIntegrationErrors') then raise exception using errcode='42501',message='finance scope denied';end if;
 if v_limit not between 1 and 200 then raise exception using errcode='22023',message='invalid page limit';end if;
 if p_cursor is not null then if p_cursor!~'^[0-9a-fA-F-]{36}$' then raise exception using errcode='22023',message='invalid cursor';end if;v_cursor_id:=p_cursor::uuid;select created_at_utc into v_cursor_time from finance.integration_errors where id=v_cursor_id;if not found then raise exception using errcode='22023',message='unknown cursor';end if;end if;
 with scoped as (select ie.* from finance.integration_errors ie where ie.legal_entity_id=p_legal_entity_id and finance_private.integration_error_is_in_scope(ie.id,p_legal_entity_id,p_dealer_account_id,p_branch_id) and (p_status is null or case ie.status when 'RETRY_SCHEDULED' then 'RETRYABLE' when 'IGNORED_WITH_APPROVAL' then 'IGNORED' else ie.status end=p_status) and (p_source_system is null or coalesce(ie.redacted_detail->>'sourceSystem',ie.source_type)=p_source_system) and (v_cursor_time is null or (ie.created_at_utc,ie.id)<(v_cursor_time,v_cursor_id)) order by ie.created_at_utc desc,ie.id desc limit v_limit+1), page as (select * from scoped order by created_at_utc desc,id desc limit v_limit)
 select coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('errorId',p.id,'sourceSystem',coalesce(p.redacted_detail->>'sourceSystem',p.source_type),'errorClass',p.source_type,'safeErrorCode',p.error_code,'status',case p.status when 'RETRY_SCHEDULED' then 'RETRYABLE' when 'IGNORED_WITH_APPROVAL' then 'IGNORED' when 'OPEN' then case when p.redacted_detail->>'retryable'='true' then 'RETRYABLE' else 'ACTION_REQUIRED' end else p.status end,'ownerUserId',null,'retryCount',p.occurrence_no-1,'occurredAtUtc',p.created_at_utc,'correlationId',p.correlation_id::text,'version',p.version) order by p.created_at_utc desc,p.id desc) from page p),'[]'::jsonb),(select pg_catalog.count(*) from scoped)>v_limit,case when (select pg_catalog.count(*) from scoped)>v_limit then (select id::text from page order by created_at_utc desc,id desc offset v_limit-1 limit 1) else null end into v_items,v_has_more,v_next_cursor;
 return pg_catalog.jsonb_build_object('items',v_items,'nextCursor',v_next_cursor,'hasMore',v_has_more);
end$$;
revoke all on function finance_private.integration_error_is_in_scope(uuid,uuid,uuid,uuid) from public,anon,authenticated;
revoke all on function finance_api.list_integration_errors(uuid,uuid,uuid,text,text,text,integer) from public,anon;
